export function blogArticle(slug: string): BlogArticle | null {
  return BLOG_ARTICLES[slug] ?? null;
}

// Prose blocks only: headings, links and deal widgets are not reading time.
export function blogWordCount(article: BlogArticle): number {
  return article.blocks.reduce((total, block) => {
    if (block.type === 'p' || block.type === 'callout') return total + block.text.split(/\s+/).length;
    if (block.type === 'ul' || block.type === 'ol') return total + block.items.join(' ').split(/\s+/).length;
    if (block.type === 'table') return total + block.rows.flat().join(' ').split(/\s+/).length;
    return total;
  }, 0);
}

export function blogReadMinutes(article: BlogArticle): number {
  return Math.max(3, Math.round(blogWordCount(article) / 220));
}
